	var markersmain = [];
	var circles = [];
	var aniMarkers = [];
	var iw = null;
	c.data.radioTypePrv = "Child Care";
	c.disableSearchBtn = true;
	c.data.alreadyexecuted = false;
	c.searchStatus = false;
	c.showSpinners = false;
	c.searchStatusCounty = false;
	$scope.$on('sp_loading_indicator', function (e, value) {
		$scope.loadingIndicator = value;
		c.disableSearchBtn = value;
		if (value) {
			document.body.style.cursor = 'wait';
		}
		else {
			c.disableSearchBtn = true;
			document.body.style.cursor = 'default';
		}
	});
	c.checkDay = function (val) {
		var isCheck = false;
		var eleOp = document.getElementsByName('operation');
		for (var t = 0; t < eleOp.length; t++) {
			if (eleOp[t].checked) {
				isCheck = true;
				break;
			}
		}
	}
	c.newsearch = function () {
		c.tabSelected("address");
		c.data.radioTypePrv = "Child Care";
		newRefresh();
	}
	c.editsearch = function () {
		c.data.showResultsTab = false;
		c.data.showResultsBodyFlag = false;
	}
	c.refresh = function () {
		newRefresh();
	}
	function newRefresh() {
		c.searchStatusCounty = false;
		c.data.showResultsBodyFlag = false;
		c.data.showResultProvider = false;
		c.data.showResultsCounty = false;
		c.data.showValidCounty = false;
		c.disableSearchBtn = true;
		c.templist = [];
		c.templistCounty = [];
		clearAllMainMarkers();
		c.data.locs = [];
		c.data.PrvByName = undefined;
		c.disableSearchBtn = true;
		c.data.locsCounty = [];
		var WheelChair = document.getElementById("WheelChair");
		var subCCA = document.getElementById("subCCA");
		var Transport = document.getElementById("Transport");
		if (typeof (WheelChair) != 'undefined' && WheelChair != null) {
			document.getElementById("WheelChair").checked = false;
		}
		if (typeof (subCCA) != 'undefined' && subCCA != null) {
			document.getElementById("subCCA").checked = false;
		}
		if (typeof (Transport) != 'undefined' && Transport != null) {
			document.getElementById("Transport").checked = false;
		}
		var eleCCType = document.getElementsByName('ccType');
		if (typeof (eleCCType) != 'undefined' && eleCCType != null) {
			for (var p = 0; p < eleCCType.length; p++) {
				eleCCType[p].checked = false;
			}
		}
		var eleAge = document.getElementsByName('age');
		if (typeof (eleAge) != 'undefined' && eleAge != null) {
			for (var i = 0; i < eleAge.length; i++) {
				eleAge[i].checked = false;
			}
		}
		var eleRate = document.getElementsByName('rate');
		if (typeof (eleRate) != 'undefined' && eleRate != null) {
			for (var j = 0; j < eleRate.length; j++) {
				eleRate[j].checked = false;
			}
		}
		var eleRadius = document.getElementsByName('radius');
		if (typeof (eleRadius) != 'undefined' && eleRadius != null) {
			for (var k = 0; k < eleRadius.length; k++) {
				eleRadius[k].checked = false;
			}
		}
		var eleOp = document.getElementsByName('operation');
		if (typeof (eleOp) != 'undefined' && eleOp != null) {
			for (var t = 0; t < eleOp.length; t++) {
				eleOp[t].checked = false;
			}
		}
